    37  enum
    38  {
    39          START_TO,
    40          DISPLAY_QUOTED,
    41          E_DISPLAY_QUOTED,
    42          DISPLAY_TOKEN,
    43          DISPLAY_TOKEN_SP,
    44          S_URI_ENCLOSED,
    45          URI_ENCLOSED,
    46          E_URI_ENCLOSED,
    47          URI_OR_TOKEN,
    48          MAYBE_URI_END,
    49          END,
    50          F_CR,
    51          F_LF,
    52          F_CRLF
    53  };
    54
    55
    56  enum
    57  {
    58          S_PARA_NAME = 20,
    59          PARA_NAME,
    60          S_EQUAL,
    61          S_PARA_VALUE,
    62          TAG1,
    63          TAG2,
    64          TAG3,
    65          PARA_VALUE_TOKEN,
    66          PARA_VALUE_QUOTED,
    67          E_PARA_VALUE
    68  };
